.done-card h2 { margin: 10px 0 4px; font-size: 22px; }
.done-card .sub { color: var(--ink-3); margin: 0 0 20px; }
.done-stats { display: flex; justify-content: center; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.stat {
  border: 1px solid var(--line); border-radius: var(--radius-s);
  padding: 10px 18px; min-width: 110px; background: #fafcfe;
}
.stat .v { font-size: 20px; font-weight: 700; font-variant-numeric: tabular-nums; }
.stat .k { font-size: 11.5px; color: var(--ink-3); }
.done-actions { display: flex; justify-content: center; gap: 10px; flex-wrap: wrap; }

/* ---------- 右栏：操作留痕 ---------- */
.audit { padding: 14px; max-height: calc(100vh - 132px); overflow: auto; position: sticky; top: 66px; }
.audit-head { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; }
.audit-head h2 { margin: 0; font-size: 13px; letter-spacing: .5px; color: var(--ink-3); flex: 1; }
.audit-count {
  font-size: 11.5px; font-variant-numeric: tabular-nums;
  background: #f1f4f8; border: 1px solid var(--line); border-radius: 999px; padding: 0 8px; color: var(--ink-2);
}
.audit-tools { display: flex; gap: 6px; margin-bottom: 12px; }
.audit-empty {
  border: 1px dashed var(--line-strong); border-radius: var(--radius-s);
  padding: 22px 14px; text-align: center; color: var(--ink-3); font-size: 12.5px;
}
