.audit-item { display: flex; gap: 9px; padding: 8px 2px; border-bottom: 1px dashed var(--line); font-size: 12.5px; }
.audit-item:last-child { border-bottom: 0; }
.audit-ico { flex: none; margin-top: 1px; }
.audit-main { flex: 1; min-width: 0; }
.audit-text { color: var(--ink-2); line-height: 1.5; }
.audit-meta { display: flex; gap: 6px; align-items: center; margin-top: 2px; }
