.check-item .txt { flex: 1; }
.check-item.is-on .txt { color: var(--ink-3); text-decoration: line-through; text-decoration-color: #a5b3c1; }
.check-progress { font-size: 12px; color: var(--ink-3); margin-top: 6px; font-variant-numeric: tabular-nums; }

.block { border-radius: var(--radius-s); padding: 13px 16px; border: 1px solid; }
.block h3 { margin: 0 0 6px; font-size: 12.5px; letter-spacing: .5px; display: flex; align-items: center; gap: 6px; }
.block p { margin: 0 0 4px; }
.block ul, .block ol { margin: 6px 0 0; padding-left: 20px; }
.block li { margin-bottom: 3px; }
.block-danger { background: var(--danger-weak); border-color: var(--danger-line); color: #7d2019; }
.block-danger h3 { color: var(--danger); }
.block-amber { background: var(--warn-weak); border-color: var(--warn-line); color: #6d4a12; }
.block-amber h3 { color: var(--warn); }
.block-ok { background: var(--ok-weak); border-color: var(--ok-line); color: #14532d; }
.block-ok h3 { color: var(--ok); }
.block-info { background: var(--info-weak); border-color: var(--info-line); color: #1c4177; }
.block-info h3 { color: var(--info); }
.block-violet { background: var(--violet-weak); border-color: var(--violet-line); color: #46307e; }
.block-violet h3 { color: var(--violet); }
.rb-cost { font-size: 12.5px; font-weight: 700; }

.expected { display: flex; gap: 9px; align-items: flex-start; }
.expected svg { flex: none; margin-top: 2px; color: var(--info); }

.action-bar {
  margin-top: 24px; padding-top: 18px; border-top: 1px solid var(--line);
  display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
}
.action-hint { font-size: 12.5px; color: var(--ink-3); }

.locked-note {
  display: flex; gap: 9px; align-items: flex-start;
  background: #f4f6f9; border: 1px solid var(--line);
  border-radius: var(--radius-s); padding: 11px 14px; margin-bottom: 14px;
  color: var(--ink-2); font-size: 13px;
}
.locked-note svg { flex: none; margin-top: 2px; color: var(--ink-3); }
.locked-note b { color: var(--ink); }

/* 完成卡片 */
.done-card { text-align: center; padding: 34px 20px 30px; }
.done-card h2 { margin: 10px 0 4px; font-size: 22px; }
.done-card .sub { color: var(--ink-3); margin: 0 0 20px; }
.done-stats { display: flex; justify-content: center; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.stat {
  border: 1px solid var(--line); border-radius: var(--radius-s);
  padding: 10px 18px; min-width: 110px; background: #fafcfe;
}
.stat .v { font-size: 20px; font-weight: 700; font-variant-numeric: tabular-nums; }
.stat .k { font-size: 11.5px; color: var(--ink-3); }
.done-actions { display: flex; justify-content: center; gap: 10px; flex-wrap: wrap; }

/* ---------- 右栏：操作留痕 ---------- */
.audit { padding: 14px; max-height: calc(100vh - 132px); overflow: auto; position: sticky; top: 66px; }
.audit-head { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; }
.audit-head h2 { margin: 0; font-size: 13px; letter-spacing: .5px; color: var(--ink-3); flex: 1; }
