.check-item input:disabled { cursor: not-allowed; }
.check-item .txt { flex: 1; }
.check-item.is-on .txt { color: var(--ink-3); text-decoration: line-through; text-decoration-color: #a5b3c1; }
.check-progress { font-size: 12px; color: var(--ink-3); margin-top: 6px; font-variant-numeric: tabular-nums; }

.block { border-radius: var(--radius-s); padding: 13px 16px; border: 1px solid; }
.block h3 { margin: 0 0 6px; font-size: 12.5px; letter-spacing: .5px; display: flex; align-items: center; gap: 6px; }
