/* ---------- 右栏：操作留痕 ---------- */
.audit { padding: 14px; max-height: min(calc(100vh - 140px), 760px); overflow: auto; }
.audit-head { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; }
.audit-head h2 { margin: 0; font-size: 13px; letter-spacing: .5px; color: var(--ink-3); flex: 1; }
.audit-count {
  font-size: 11.5px; font-variant-numeric: tabular-nums;
