60	/* ---------- 状态派生 ---------- */
61	function stepById(id) { return ALL_STEPS[ORDER[id]]; }
62	function st(id) { return state.steps[id]; }
63	function isComplete(id) { var s = st(id); return s.done || s.executed; }
64	function activeIndex() {
65	  for (var i = 0; i < TOTAL; i++) if (!isComplete(ALL_STEPS[i].id)) return i;
66	  return TOTAL; /* 全部完成 */
67	}
68	function activeStep() { return activeIndex() < TOTAL ? ALL_STEPS[activeIndex()] : null; }
69	function isLocked(id) { return ORDER[id] > activeIndex(); }
70	function flowCompleted() { return activeIndex() >= TOTAL; }
71	function progressCount() { return ALL_STEPS.filter(function (s) { return isComplete(s.id); }).length; }
72	function remainingIrreversible() {
73	  return IRREVERSIBLE.filter(function (s) { return !isComplete(s.id); }).length;
74	}
75	function rollbackCount() { return state.events.filter(function (e) { return e.type === "rollback"; }).length; }
76	function lastExecutedIrreversible() {
77	  var found = null;
78	  ALL_STEPS.forEach(function (s) { if (s.reversibility === "irreversible" && st(s.id).executed) found = s; });
79	  return found;
80	}
81	function phaseProgress(phase) {
82	  var done = 0;
83	  phase.steps.forEach(function (s) { if (isComplete(s.id)) done++; });
84	  return done + "/" + phase.steps.length;
85	}
86	function checksDone(id) {
87	  var s = st(id), n = 0;
88	  s.checks.forEach(function (c) { if (c) n++; });
89	  return n;
90	}
