350	function gateAcksAll() {
351	  var step = gateStep();
352	  if (!step) return false;
353	  for (var i = 0; i < step.acks.length; i++) if (!state.gateAcks[i]) return false;
354	  return true;
355	}
356	function gateCodeOk() { return state.gateCode.trim() === TICKET; }
357	function gateReady() { return gateAcksAll() && gateCodeOk(); }
358	function gateHint() {
359	  var step = gateStep();
360	  var n = step.acks.filter(function (_, i) { return state.gateAcks[i]; }).length;
361	  return "确认项 " + n + "/" + step.acks.length + " · 发布单号" + (gateCodeOk() ? "已匹配" : "未匹配");
362	}
363	function renderGate() {
364	  var root = document.getElementById("gate-root");
365	  var step = gateStep();
366	  if (!step) { root.innerHTML = ""; return; }
367	  var s = st(step.id);
368	  var impact = step.impact.map(function (x) { return "<li>" + esc(x) + "</li>"; }).join("");
369	  var acks = step.acks.map(function (a, i) {
370	    return '<label class="ack-item"><input type="checkbox" data-change="gate-ack" data-index="' + i + '"' +
371	      (state.gateAcks[i] ? " checked" : "") + '><span>' + esc(a) + '</span></label>';
372	  }).join("");
373	  root.innerHTML =
374	    '<div class="gate-overlay">' +
375	    '<div class="gate-dialog" role="dialog" aria-modal="true" aria-labelledby="gate-title" id="gate-dialog" tabindex="-1">' +
376	      '<div class="gate-head"><span class="gate-kicker">' + I.bolt + ' 不可逆操作 · 确认关卡</span>' +
377	      '<h2 id="gate-title">' + esc(step.name) + '</h2></div>' +
378	      '<div class="gate-scroll">' +
379	        '<div class="block block-danger"><h3>后果陈述</h3><p>' + esc(step.consequence) + '</p><ul>' + impact + '</ul></div>' +
380	        rollbackBlockHtml(step, { titleSuffix: "执行前确认" }) +
381	        '<div class="block"><h3>确认项（须全部勾选）</h3>' + acks + '</div>' +
382	        '<div class="block"><h3>发布单号确认</h3>' +
383	        '<p>输入发布单号 <code>' + esc(TICKET) + '</code> 以确认执行。</p>' +
384	        '<div class="code-row"><input class="code-input" type="text" data-input="gate-code" placeholder="输入发布单号" ' +
385	        'aria-label="发布单号确认" autocomplete="off" spellcheck="false"></div>' +
386	        (state.gateError ? '<p class="form-error" role="alert">' + I.warn + ' ' + esc(state.gateError) + '</p>' : '') +
387	        '</div>' +
388	      '</div>' +
389	      '<div class="gate-foot"><span class="gate-hint" id="gate-hint">' + gateHint() + '</span>' +
390	      '<div class="gate-foot-btns">' +
391	      '<button class="btn" data-action="gate-cancel" data-fk="act:gcancel">取消（无任何变更）</button>' +
392	      '<button class="btn btn-danger-solid" data-action="gate-confirm" data-fk="act:gconfirm"' + (s.done ? " disabled" : "") + '>确认执行</button>' +
393	      '</div></div>' +
394	    '</div></div>';
395	}
396	function openGate(id) {
397	  state.gateOpenFor = id;
398	  state.gateAcks = {};
399	  state.gateCode = "";
400	  state.gateError = "";
401	  addEvent("confirm", id, "打开确认关卡：" + stepById(id).name);
402	  render();
403	  var dlg = document.getElementById("gate-dialog");
404	  if (dlg) dlg.focus();
405	}
406	function cancelGate() {
407	  if (!state.gateOpenFor) return;
408	  var id = state.gateOpenFor;
409	  state.gateOpenFor = null;
410	  render();
411	  var btn = document.querySelector('[data-fk="act:exec:' + id + '"]');
412	  if (btn) btn.focus();
413	}
414	function confirmGate() {
415	  var step = gateStep();
416	  if (!step) return;
417	  if (!gateAcksAll() && !gateCodeOk()) state.gateError = "确认项未全部勾选，且发布单号不匹配。";
418	  else if (!gateAcksAll()) state.gateError = "确认项未全部勾选，无法执行。";
419	  else if (!gateCodeOk()) state.gateError = "发布单号不匹配，请核对后重新输入（" + TICKET + "）。";
420	  if (state.gateError) { renderGate(); return; }
421	  /* 放行执行 */
422	  state.gateOpenFor = null;
423	  var s = st(step.id);
424	  s.executed = true;
425	  s.rolledBack = false;
426	  s.checks = s.checks.map(function () { return true; });
427	  addEvent("confirm", step.id, "通过确认关卡（确认项 " + step.acks.length + "/" + step.acks.length + "，发布单号匹配）");
428	  addEvent("execute", step.id, "执行不可逆操作：" + step.name);
429	  advanceAfter(step.id);
430	}
431	
432	/* ---------- 动作 ---------- */
433	function advanceAfter(id) {
434	  var act = activeStep();
435	  state.selectedId = act ? act.id : id;
436	  if (!act) state.completedAt = Date.now();
437	  render();
438	  var n = document.querySelector('[data-fk="step:' + state.selectedId + '"]');
439	  if (n) n.focus({ preventScroll: false });
440	}
441	function completeStep(id) {
442	  if (isLocked(id) || isComplete(id)) return;
443	  var step = stepById(id);
444	  if (checksDone(id) !== step.checklist.length) return;
445	  st(id).done = true;
446	  addEvent(step.kind === "verify" ? "verify" : "complete", id,
447	    (step.kind === "verify" ? "验证通过：" : "完成：") + step.name);
448	  advanceAfter(id);
449	}
450	function toggleCheck(id, idx) {
451	  if (isLocked(id) || isComplete(id)) return;
452	  var s = st(id);
453	  s.checks[idx] = !s.checks[idx];
454	  render();
455	}
456	function rollbackStep(id) {
457	  var step = stepById(id);
458	  if (!st(id).executed || flowCompleted()) return;
459	  var reset = 0;
460	  for (var i = ORDER[id]; i < TOTAL; i++) {
461	    var sid = ALL_STEPS[i].id, s = st(sid);
462	    if (isComplete(sid)) reset++;
463	    s.done = false; s.executed = false;
464	    s.checks = s.checks.map(function () { return false; });
465	    s.rolledBack = (sid === id);
466	  }
467	  state.completedAt = null;
468	  addEvent("rollback", id, "回滚「" + step.name + "」，按恢复路径复位其后 " + reset + " 个步骤");
469	  state.selectedId = id;
470	  render();
471	}
472	function doReset() {
473	  if (!state.resetArmed) {
474	    state.resetArmed = true;
475	    renderHeader();
476	    clearTimeout(state.resetTimer);
477	    state.resetTimer = setTimeout(function () { state.resetArmed = false; renderHeader(); }, 4000);
478	    return;
479	  }
480	  clearTimeout(state.resetTimer);
481	  state = createState();
482	  render();
483	}
484	
485	/* ---------- 留痕导出 ---------- */
486	function auditSnapshot() {
487	  return {
488	    release: { ticket: TICKET, title: RELEASE.title, window: RELEASE.window },
489	    exportedAt: new Date().toISOString(),
490	    summary: {
491	      stepsTotal: TOTAL, stepsCompleted: progressCount(),
492	      irreversibleExecuted: IRREVERSIBLE.filter(function (s) { return st(s.id).executed; }).length,
493	      rollbacks: rollbackCount(),
494	      completed: flowCompleted()
495	    },
496	    events: state.events
497	  };
498	}
499	function copyAudit() {
500	  var lines = state.events.map(function (e) {
501	    return e.t + " [" + e.type + "] " + e.text;
502	  });
503	  var text = "操作留痕 — " + RELEASE.title + "（" + TICKET + "）\n" +
504	    "步骤完成 " + progressCount() + "/" + TOTAL + " · 回滚 " + rollbackCount() + " 次\n" +
505	    "----------------------------------------\n" + lines.join("\n");
506	  copyText(text);
507	  flashCopied();
508	}
509	function exportAudit() {
510	  var blob = new Blob([JSON.stringify(auditSnapshot(), null, 2)], { type: "application/json" });
511	  var a = document.createElement("a");
512	  a.href = URL.createObjectURL(blob);
513	  a.download = "audit-" + TICKET + ".json";
514	  document.body.appendChild(a); a.click(); a.remove();
515	  setTimeout(function () { URL.revokeObjectURL(a.href); }, 2000);
516	}
517	function copyText(text) {
518	  if (navigator.clipboard && window.isSecureContext) {
519	    navigator.clipboard.writeText(text).catch(function () { fallbackCopy(text); });
520	    return;
521	  }
522	  fallbackCopy(text);
523	}
524	function fallbackCopy(text) {
525	  var ta = document.createElement("textarea");
526	  ta.value = text;
527	  ta.style.position = "fixed"; ta.style.opacity = "0";
528	  document.body.appendChild(ta);
529	  ta.select();
530	  try { document.execCommand("copy"); } catch (e) { /* 忽略：用户可改用导出 */ }
531	  ta.remove();
532	}
533	function flashCopied() {
534	  var btn = document.querySelector('[data-action="copy-audit"]');
535	  if (!btn) return;
536	  var old = btn.textContent;
537	  btn.textContent = "已复制 ✓";
538	  setTimeout(function () { btn.textContent = old; }, 1200);
539	}
540	
541	/* ---------- 渲染入口（保留焦点） ---------- */
542	function render() {
543	  var el = document.activeElement;
544	  var fk = el && el.getAttribute ? el.getAttribute("data-fk") : null;
545	  renderHeader(); renderRail(); renderDetail(); renderAudit(); renderGate();
546	  if (fk) {
547	    var n = document.querySelector('[data-fk="' + fk + '"]');
548	    if (n) n.focus({ preventScroll: true });
549	  }
550	}
551	
552	/* ---------- 事件绑定 ---------- */
553	document.addEventListener("click", function (e) {
554	  var el = e.target.closest("[data-action]");
555	  if (!el) return;
556	  var a = el.dataset.action, id = el.dataset.id;
557	  if (a === "select") { state.selectedId = id; render(); }
558	  else if (a === "complete") completeStep(id);
559	  else if (a === "open-gate") openGate(id);
560	  else if (a === "gate-cancel") cancelGate();
561	  else if (a === "gate-confirm") confirmGate();
562	  else if (a === "rollback") rollbackStep(id);
563	  else if (a === "copy-audit") copyAudit();
564	  else if (a === "export-audit") exportAudit();
565	  else if (a === "reset") doReset();
566	});
567	document.addEventListener("change", function (e) {
568	  var el = e.target.closest("[data-change]");
569	  if (!el) return;
570	  if (el.dataset.change === "check") toggleCheck(el.dataset.id, Number(el.dataset.index));
571	  else if (el.dataset.change === "gate-ack") {
572	    state.gateAcks[Number(el.dataset.index)] = el.checked;
573	    state.gateError = "";
574	    renderGate();
575	  }
576	});
577	document.addEventListener("input", function (e) {
578	  if (e.target.matches('[data-input="gate-code"]')) {
579	    state.gateCode = e.target.value;
580	    state.gateError = "";
581	    var hint = document.getElementById("gate-hint");
582	    if (hint) hint.textContent = gateHint();
583	  }
584	});
585	document.addEventListener("keydown", function (e) {
586	  if (e.key === "Escape" && state.gateOpenFor) cancelGate();
587	});
588	/* 左栏列表 roving tabindex：↑/↓/Home/End 在步骤间移动焦点，Enter/Space 原生点击选中 */
589	document.getElementById("region-step-rail").addEventListener("keydown", function (e) {
590	  if (e.key !== "ArrowDown" && e.key !== "ArrowUp" && e.key !== "Home" && e.key !== "End") return;
591	  var steps = Array.prototype.slice.call(this.querySelectorAll(".step"));
592	  if (!steps.length) return;
593	  var idx = steps.indexOf(document.activeElement);
594	  if (idx === -1) return;
595	  e.preventDefault();
596	  var next;
597	  if (e.key === "ArrowDown") next = steps[Math.min(idx + 1, steps.length - 1)];
598	  else if (e.key === "ArrowUp") next = steps[Math.max(idx - 1, 0)];
599	  else if (e.key === "End") next = steps[steps.length - 1];
600	  else next = steps[0];
601	  next.focus();
602	});
603	document.getElementById("gate-root").addEventListener("click", function (e) {
604	  if (e.target.classList.contains("gate-overlay")) cancelGate();
605	});
606	
607	/* ---------- 启动：同步渲染，页面加载完成即 ready（留痕初始为空态） ---------- */
608	render();
